import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const frontendDir = path.resolve(__dirname, '..');
const distDir = path.resolve(frontendDir, 'dist');

// Read base template generated by vite build
const baseTemplatePath = path.resolve(distDir, 'index.html');
if (!fs.existsSync(baseTemplatePath)) {
  console.error('dist/index.html not found! Run vite build first.');
  process.exit(1);
}

const baseTemplate = fs.readFileSync(baseTemplatePath, 'utf8');

// Import pagesSEO data
// We can parse or define the route definitions
const { pagesSEO, COMPANY_INFO } = await import('../src/data/seoData.ts');

console.log(`Starting SSG Prerendering for ${Object.keys(pagesSEO).length} routes...`);

for (const [routePath, seo] of Object.entries(pagesSEO)) {
  const isArabic = seo.lang === 'ar' || routePath.startsWith('/ar');
  const dir = isArabic ? 'rtl' : 'ltr';
  const lang = isArabic ? 'ar' : 'en';

  // Compute canonical & hreflangs
  const englishPath = routePath.startsWith('/ar')
    ? (routePath.replace(/^\/ar/, '') || '/')
    : routePath;
  const arabicPath = routePath.startsWith('/ar')
    ? routePath
    : (routePath === '/' ? '/ar' : `/ar${routePath}`);

  const enCanonical = `${COMPANY_INFO.canonicalHost}${englishPath === '/' ? '/' : englishPath}`;
  const arCanonical = `${COMPANY_INFO.canonicalHost}${arabicPath}`;
  const xDefault = enCanonical;

  // Build JSON-LD schemas
  const schemaGraph = [
    {
      "@type": "WebSite",
      "@id": "https://www.naviads.com.sa/#website",
      "url": "https://www.naviads.com.sa/",
      "name": "Navi Ads | Sky Cleaning Riyadh",
      "alternateName": ["Sky Cleaning", "Sky Cleaning Riyadh", "SkyCleaning", "Sky Cleaning Services", "سكاي كلينينج", "سكاي كلينينج الرياض", "شركة نافيآدز"],
      "inLanguage": ["en-SA", "ar-SA"],
      "publisher": {
        "@id": "https://www.naviads.com.sa/#organization"
      }
    },
    {
      "@type": ["Organization", "LocalBusiness", "ProfessionalService"],
      "@id": "https://www.naviads.com.sa/#organization",
      "name": "Navi Ads (Sky Cleaning Services)",
      "alternateName": ["Sky Cleaning", "Sky Cleaning Riyadh", "SkyCleaning", "سكاي كلينينج", "سكاي كلينينج الرياض", "شركة نافيآدز"],
      "legalName": COMPANY_INFO.nameEn,
      "taxID": COMPANY_INFO.crNumber,
      "brand": {
        "@type": "Brand",
        "name": "Sky Cleaning",
        "alternateName": ["Sky Cleaning Services", "Sky Cleaning Riyadh", "سكاي كلينينج", "سكاي للتنظيف"]
      },
      "knowsAbout": ["Sky Cleaning", "Sky Cleaning Riyadh", "Building Cleaning", "Office Cleaning", "Facade Cleaning", "Manpower Supply Riyadh"],
      "url": COMPANY_INFO.canonicalHost,
      "logo": `${COMPANY_INFO.canonicalHost}/images/logo/logo.png`,
      "image": `${COMPANY_INFO.canonicalHost}/sky_cleaning_irata.png`,
      "telephone": COMPANY_INFO.phone,
      "email": COMPANY_INFO.email,
      "priceRange": "$$",
      "currenciesAccepted": "SAR",
      "address": {
        "@type": "PostalAddress",
        "streetAddress": "Building No. 1258, Street No. 1005, King Khalid International Airport District",
        "addressLocality": "Riyadh",
        "addressRegion": "Riyadh Province",
        "addressCountry": "SA"
      },
      "geo": {
        "@type": "GeoCoordinates",
        "latitude": "24.9576",
        "longitude": "46.6988"
      },
      "areaServed": [
        { "@type": "City", "name": "Riyadh" },
        { "@type": "Country", "name": "Saudi Arabia" }
      ],
      "openingHoursSpecification": [
        {
          "@type": "OpeningHoursSpecification",
          "dayOfWeek": ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday"],
          "opens": "08:00",
          "closes": "18:00"
        }
      ]
    }
  ];

  if (seo.breadcrumbs && seo.breadcrumbs.length > 0) {
    schemaGraph.push({
      "@type": "BreadcrumbList",
      "itemListElement": seo.breadcrumbs.map((crumb, idx) => ({
        "@type": "ListItem",
        "position": idx + 1,
        "name": crumb.name,
        "item": crumb.url
      }))
    });
  }

  if (routePath.includes('/services/')) {
    schemaGraph.push({
      "@type": "Service",
      "name": seo.h1,
      "description": seo.description,
      "provider": {
        "@type": "LocalBusiness",
        "name": COMPANY_INFO.nameEn,
        "alternateName": COMPANY_INFO.nameAr,
        "telephone": COMPANY_INFO.phone,
        "url": COMPANY_INFO.canonicalHost
      },
      "areaServed": {
        "@type": "City",
        "name": "Riyadh"
      },
      "url": seo.canonical
    });
  }

  if (seo.faqs && seo.faqs.length > 0) {
    schemaGraph.push({
      "@type": "FAQPage",
      "mainEntity": seo.faqs.map(faq => ({
        "@type": "Question",
        "name": faq.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": faq.answer
        }
      }))
    });
  }

  // Generate Semantic Pre-rendered HTML Body
  const preRenderedHtml = `
    <header class="bg-white border-b border-slate-100 py-4 px-6">
      <div class="max-w-7xl mx-auto flex items-center justify-between">
        <a href="${isArabic ? '/ar' : '/'}" class="font-extrabold text-xl text-slate-900">
          ${isArabic ? COMPANY_INFO.nameAr : COMPANY_INFO.nameEn}
          <span class="block text-[10px] text-emerald-600 font-bold uppercase tracking-widest">${isArabic ? 'خدمات النظافة والعمالة' : 'Sky Cleaning & Manpower'}</span>
        </a>
        <div class="flex items-center gap-4 text-sm font-semibold">
          <a href="${isArabic ? '/ar/services/cleaning' : '/services/cleaning'}" class="text-slate-700 hover:text-emerald-600">${isArabic ? 'تنظيف سكاي' : 'Sky Cleaning'}</a>
          <a href="${isArabic ? '/ar/services/manpower' : '/services/manpower'}" class="text-slate-700 hover:text-emerald-600">${isArabic ? 'توريد العمالة' : 'Manpower'}</a>
          <a href="${isArabic ? '/ar/riyadh' : '/riyadh'}" class="text-slate-700 hover:text-emerald-600">${isArabic ? 'الرياض' : 'Riyadh'}</a>
          <a href="${isArabic ? '/ar/contact' : '/contact'}" class="bg-emerald-600 text-white px-4 py-2 rounded-xl">${isArabic ? 'طلب تسعير' : 'Get Quote'}</a>
        </div>
      </div>
    </header>

    <main class="py-16 px-6 bg-slate-50 min-h-[80vh]">
      <div class="max-w-5xl mx-auto">
        ${seo.breadcrumbs && seo.breadcrumbs.length > 1 ? `
          <nav aria-label="breadcrumb" class="text-xs text-slate-500 mb-6 flex gap-2">
            ${seo.breadcrumbs.map((b, i) => `<span>${i > 0 ? '/' : ''} <a href="${b.url}" class="hover:underline">${b.name}</a></span>`).join(' ')}
          </nav>
        ` : ''}

        <div class="inline-block px-3 py-1 bg-emerald-100 text-emerald-800 rounded-full text-xs font-bold mb-4">
          ${isArabic ? 'سجل تجاري معتمد: 7051048754 — الرياض' : 'CR: 7051048754 — Riyadh, Saudi Arabia'}
        </div>

        <h1 class="text-3xl sm:text-5xl font-extrabold text-slate-900 tracking-tight mb-6">
          ${seo.h1}
        </h1>

        <p class="text-lg sm:text-xl text-slate-600 mb-8 leading-relaxed max-w-3xl">
          ${seo.subtitle}
        </p>

        <div class="flex flex-wrap gap-4 mb-12">
          <a href="${COMPANY_INFO.telUrl}" class="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-6 py-3.5 rounded-xl shadow-md inline-flex items-center gap-2">
            📞 <span>${isArabic ? 'اتصل الآن: 0537799389' : 'Call: +966 53 779 9389'}</span>
          </a>
          <a href="${COMPANY_INFO.whatsappUrl}" target="_blank" rel="noopener noreferrer" class="bg-teal-700 hover:bg-teal-800 text-white font-bold px-6 py-3.5 rounded-xl shadow-md inline-flex items-center gap-2">
            💬 <span>${isArabic ? 'واتساب: 0537799389' : 'WhatsApp Inquiry'}</span>
          </a>
          <a href="${isArabic ? '/ar/contact' : '/contact'}" class="bg-white border border-slate-300 text-slate-800 font-semibold px-6 py-3.5 rounded-xl hover:bg-slate-100">
            <span>${isArabic ? 'طلب عرض سعر رسمي' : 'Request Quote'}</span>
          </a>
        </div>

        <section class="bg-white p-8 rounded-3xl border border-slate-200/80 shadow-sm mb-10">
          <h2 class="text-2xl font-bold text-slate-900 mb-4">${isArabic ? 'تفاصيل الخدمة ونطاق العمل' : 'Service Details & Operational Scope'}</h2>
          <p class="text-slate-600 leading-relaxed text-base mb-6">
            ${seo.description}
          </p>
          <div class="grid sm:grid-cols-2 gap-4 text-sm text-slate-700 font-medium">
            <div class="p-4 bg-emerald-50 rounded-xl">✓ ${isArabic ? 'كوادر نظامية ومدربة بمعايير سلامة عالية' : 'Trained and fully compliant workforce'}</div>
            <div class="p-4 bg-sky-50 rounded-xl">✓ ${isArabic ? 'استجابة سريعة وتغطية شاملة لكافة أحياء الرياض' : 'Rapid dispatch and full Riyadh coverage'}</div>
          </div>
        </section>

        ${seo.faqs && seo.faqs.length > 0 ? `
          <section class="bg-white p-8 rounded-3xl border border-slate-200/80 shadow-sm mb-10">
            <h2 class="text-2xl font-bold text-slate-900 mb-6">${isArabic ? 'الأسئلة الشائعة' : 'Frequently Asked Questions'}</h2>
            <div class="space-y-6">
              ${seo.faqs.map(f => `
                <div class="border-b border-slate-100 pb-4 last:border-none">
                  <h3 class="text-lg font-bold text-slate-900 mb-2">${f.question}</h3>
                  <p class="text-slate-600 text-sm leading-relaxed">${f.answer}</p>
                </div>
              `).join('')}
            </div>
          </section>
        ` : ''}

        <section class="bg-slate-900 text-white p-8 rounded-3xl shadow-xl">
          <h2 class="text-xl font-bold mb-3">${isArabic ? 'بيانات التواصل والاعتماد الرسمي' : 'Official Business Details'}</h2>
          <p class="text-sm text-slate-300 mb-4">${isArabic ? 'شركة نافيآدز — سجل تجاري رقم: 7051048754' : 'Navi Ads Company — CR: 7051048754'}</p>
          <p class="text-xs text-slate-400 leading-relaxed">
            ${isArabic ? COMPANY_INFO.addressAr : COMPANY_INFO.addressEn}<br/>
            ${isArabic ? 'هاتف / واتساب:' : 'Phone / WhatsApp:'} ${COMPANY_INFO.phoneFormatted} | ${COMPANY_INFO.email}
          </p>
        </section>
      </div>
    </main>

    <footer class="bg-slate-950 text-slate-400 py-10 px-6 border-t border-slate-800 text-xs">
      <div class="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>© ${new Date().getFullYear()} ${isArabic ? COMPANY_INFO.nameAr : COMPANY_INFO.nameEn}. CR: ${COMPANY_INFO.crNumber}</div>
        <div class="flex gap-4">
          <a href="${isArabic ? '/ar/services/cleaning' : '/services/cleaning'}" class="hover:text-white">${isArabic ? 'تنظيف سكاي' : 'Sky Cleaning'}</a>
          <a href="${isArabic ? '/ar/services/manpower' : '/services/manpower'}" class="hover:text-white">${isArabic ? 'توريد عمالة' : 'Manpower'}</a>
          <a href="${isArabic ? '/ar/riyadh' : '/riyadh'}" class="hover:text-white">${isArabic ? 'الرياض' : 'Riyadh'}</a>
          <a href="${isArabic ? '/ar/privacy-policy' : '/privacy-policy'}" class="hover:text-white">${isArabic ? 'الخصوصية' : 'Privacy'}</a>
          <a href="${isArabic ? '/ar/terms' : '/terms'}" class="hover:text-white">${isArabic ? 'الشروط' : 'Terms'}</a>
        </div>
      </div>
    </footer>
  `;

  // Clone template and replace placeholders
  let html = baseTemplate;

  // Replace lang and dir
  html = html.replace(/<html lang="[^"]*"/i, `<html lang="${lang}" dir="${dir}"`);

  // Replace title
  html = html.replace(/<title>[\s\S]*?<\/title>/i, `<title>${seo.title}</title>`);

  // Replace description
  html = html.replace(/<meta name="description" content="[^"]*"/i, `<meta name="description" content="${seo.description}"`);

  // Replace keywords
  html = html.replace(/<meta name="keywords" content="[^"]*"/i, `<meta name="keywords" content="${seo.keywords}"`);

  // Replace canonical
  html = html.replace(/<link rel="canonical" href="[^"]*"/i, `<link rel="canonical" href="${seo.canonical}"`);

  // Replace hreflang alternates
  html = html.replace(/<link rel="alternate" hreflang="en-SA" href="[^"]*"/i, `<link rel="alternate" hreflang="en-SA" href="${enCanonical}"`);
  html = html.replace(/<link rel="alternate" hreflang="ar-SA" href="[^"]*"/i, `<link rel="alternate" hreflang="ar-SA" href="${arCanonical}"`);
  html = html.replace(/<link rel="alternate" hreflang="x-default" href="[^"]*"/i, `<link rel="alternate" hreflang="x-default" href="${xDefault}"`);

  // Replace Open Graph
  html = html.replace(/<meta property="og:title" content="[^"]*"/i, `<meta property="og:title" content="${seo.title}"`);
  html = html.replace(/<meta property="og:description" content="[^"]*"/i, `<meta property="og:description" content="${seo.description}"`);
  html = html.replace(/<meta property="og:url" content="[^"]*"/i, `<meta property="og:url" content="${seo.canonical}"`);
  html = html.replace(/<meta property="og:locale" content="[^"]*"/i, `<meta property="og:locale" content="${isArabic ? 'ar_SA' : 'en_SA'}"`);
  html = html.replace(/<meta property="og:locale:alternate" content="[^"]*"/i, `<meta property="og:locale:alternate" content="${isArabic ? 'en_SA' : 'ar_SA'}"`);

  // Replace Twitter
  html = html.replace(/<meta name="twitter:title" content="[^"]*"/i, `<meta name="twitter:title" content="${seo.title}"`);
  html = html.replace(/<meta name="twitter:description" content="[^"]*"/i, `<meta name="twitter:description" content="${seo.description}"`);

  // Replace JSON-LD Schema
  const schemaRegex = /<script type="application\/ld\+json">[\s\S]*?<\/script>/i;
  const newSchemaScript = `<script type="application/ld+json">\n${JSON.stringify({ "@context": "https://schema.org", "@graph": schemaGraph }, null, 2)}\n</script>`;
  html = html.replace(schemaRegex, newSchemaScript);

  // Inject Pre-rendered Body into <div id="root"></div>
  html = html.replace('<div id="root"></div>', `<div id="root">${preRenderedHtml}</div>`);

  // Determine output directory & file
  const relativePath = routePath === '/' ? 'index.html' : path.join(routePath.replace(/^\//, ''), 'index.html');
  const targetFilePath = path.resolve(distDir, relativePath);
  const targetFileDir = path.dirname(targetFilePath);

  if (!fs.existsSync(targetFileDir)) {
    fs.mkdirSync(targetFileDir, { recursive: true });
  }

  fs.writeFileSync(targetFilePath, html, 'utf8');
  console.log(`✓ Pre-rendered: ${routePath} -> dist/${relativePath}`);
}

console.log('Static Prerendering complete for all routes!');
